import type { GeneratedWorkbook } from '../domain/model';
import { parseGeneratedWorkbook } from './validate';

/** Loads the workbook data generated by `npm run data`. The JSON is split into its own chunk. */
export async function loadWorkbookData(): Promise<GeneratedWorkbook> {
  const module = await import('./creatures.generated.json');
  return parseGeneratedWorkbook(module.default);
}
